import React, { useState } from 'react';
import './Usuarios.css';

const Usuarios = () => {
  const [users, setUsers] = useState([
    {
      id: 1,
      nombre: 'Juan Pérez',
      correo: 'juan.perez@morapack.com',
      rol: 'admin',
      estado: 'active'
    },
    {
      id: 2,
      nombre: 'María García',
      correo: 'maria.garcia@morapack.com',
      rol: 'operator',
      estado: 'active'
    },
    {
      id: 3,
      nombre: 'Carlos López',
      correo: 'carlos.lopez@morapack.com',
      rol: 'operator',
      estado: 'inactive'
    }
  ]);

  const [searchTerm, setSearchTerm] = useState('');
  const [roleFilter, setRoleFilter] = useState('all');
  const [showAddModal, setShowAddModal] = useState(false);
  const [newUser, setNewUser] = useState({
    nombre: '',
    correo: '',
    rol: 'operator',
    estado: 'active'
  });

  const filteredUsers = users.filter(user => {
    const matchesSearch = user.nombre.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         user.correo.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesRole = roleFilter === 'all' || user.rol === roleFilter;
    return matchesSearch && matchesRole;
  });

  const handleAddUser = () => {
    if (newUser.nombre && newUser.correo) {
      setUsers([...users, {
        ...newUser,
        id: Date.now()
      }]);
      setNewUser({ nombre: '', correo: '', rol: 'operator', estado: 'active' });
      setShowAddModal(false);
    }
  };

  const handleDeleteUser = (id) => {
    if (window.confirm('¿Está seguro de eliminar este usuario?')) {
      setUsers(users.filter(user => user.id !== id));
    }
  };

  return (
    <div className="usuarios-container">
      <div className="control-panel">
        <h2>Gestión de Usuarios</h2>

        <div className="user-actions">
          <button className="user-btn add-user" onClick={() => setShowAddModal(true)}>
            <i className="fas fa-user-plus"></i> Agregar Usuario
          </button>
          <div className="search-box">
            <input 
              type="text" 
              placeholder="Buscar por nombre, correo o rol..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            <i className="fas fa-search"></i>
          </div>
        </div>

        <div className="user-filters">
          <label>Filtrar por rol:</label>
          <select value={roleFilter} onChange={(e) => setRoleFilter(e.target.value)}>
            <option value="all">Todos los roles</option>
            <option value="admin">Administradores</option>
            <option value="operator">Operarios</option>
          </select>
        </div>

        <div className="user-table">
          <table>
            <thead>
              <tr>
                <th>Nombre</th>
                <th>Correo</th>
                <th>Rol</th>
                <th>Estado</th>
                <th>Acciones</th>
              </tr>
            </thead>
            <tbody>
              {filteredUsers.map(user => (
                <tr key={user.id}>
                  <td>{user.nombre}</td>
                  <td>{user.correo}</td>
                  <td>
                    <span className={`role-badge ${user.rol}`}>
                      {user.rol === 'admin' ? 'Administrador' : 'Operario'}
                    </span>
                  </td>
                  <td>
                    <span className={`status-badge ${user.estado}`}>
                      {user.estado === 'active' ? 'Activo' : 'Inactivo'}
                    </span>
                  </td>
                  <td>
                    <button className="action-btn edit">
                      <i className="fas fa-edit"></i>
                    </button>
                    <button className="action-btn delete" onClick={() => handleDeleteUser(user.id)}>
                      <i className="fas fa-trash"></i>
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal para agregar usuario */}
      {showAddModal && (
        <div className="modal-overlay">
          <div className="modal-content">
            <h3>Agregar Nuevo Usuario</h3>
            <div className="form-group">
              <label>Nombre:</label>
              <input
                type="text"
                value={newUser.nombre}
                onChange={(e) => setNewUser({...newUser, nombre: e.target.value})}
              />
            </div>
            <div className="form-group">
              <label>Correo:</label>
              <input
                type="email"
                value={newUser.correo}
                onChange={(e) => setNewUser({...newUser, correo: e.target.value})}
              />
            </div>
            <div className="form-group">
              <label>Rol:</label>
              <select 
                value={newUser.rol}
                onChange={(e) => setNewUser({...newUser, rol: e.target.value})}
              >
                <option value="operator">Operario</option>
                <option value="admin">Administrador</option>
              </select>
            </div>
            <div className="modal-actions">
              <button className="btn-cancel" onClick={() => setShowAddModal(false)}>
                Cancelar
              </button>
              <button className="btn-save" onClick={handleAddUser}>
                Guardar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Usuarios;
